<template><section class="item-editor"><header><h4>{{ title }} *</h4><button type="button" @click="$emit('add')"><Plus :size="15" />추가</button></header><article v-for="(item,index) in items" :key="index"><div><input v-model="item[nameKey]" :placeholder="namePlaceholder" /><input v-model="item.reference_url" placeholder="참조 URL (선택)" /></div><textarea v-model="item.description" rows="2" placeholder="이 자산에서의 역할과 활용 방식을 작성하세요."></textarea><button type="button" :disabled="items.length===1" @click="$emit('remove',index)"><X :size="15" /></button></article></section></template>
<script setup>import{Plus,X}from"lucide-vue-next";defineProps({title:String,items:Array,nameKey:String,namePlaceholder:String});defineEmits(["add","remove"]);</script>
